const request = $('POST /integrations/test').item.json || {};
const body = request.body || {};
const integrationKey = String(body.integrationKey || '').trim();
const envKey = String(body.environmentKey || 'local');
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const checkedByRaw = body.checkedBy || body.checkedByUserId || null;
const checkedBy = checkedByRaw && uuidPattern.test(String(checkedByRaw)) ? String(checkedByRaw) : null;
const checkedByName = body.checkedByName || body.actorName || checkedByRaw || 'n8n';
const row = $items('Fetch Integration For Test').map(i => i.json).find(i => i && i.integration_key) || null;
const health = $('Fetch Live Health Snapshot').item.json || {};
const services = Array.isArray(health.services) ? health.services : [];
const now = new Date().toISOString();
function service(name) { return services.find(s => String(s.name || '').toLowerCase() === name.toLowerCase()) || null; }
function probeFor(key, displayName) {
  if (!row) return { status: 'not_configured', message: `No ${key} settings found for ${envKey}`, detail: { probe: 'missing-settings' } };
  if (!row.enabled) return { status: 'not_configured', message: `${displayName || key} is disabled`, detail: { probe: 'disabled' } };
  if (key === 'supabase') { const db = service('Supabase DB'); const storage = service('Supabase Storage'); const bad = [db, storage].find(s => s && !['ok', 'operational'].includes(s.status)); return { status: bad ? 'degraded' : 'operational', message: [db?.detail, storage?.detail].filter(Boolean).join(' | ') || 'Supabase DB and Storage reachable', detail: { db, storage, probe: 'health-workflow' } }; }
  if (key === 'chroma') { const s = service('ChromaDB'); return { status: s?.status === 'ok' ? 'operational' : (s?.status || 'unreachable'), message: s?.detail || 'Chroma health result unavailable', detail: { service: s, probe: 'health-workflow' } }; }
  if (key === 'microservices') { const extractor = service('FastAPI Extractor'); const converter = service('Converter Service'); const bad = [extractor, converter].find(s => s && !['ok', 'operational'].includes(s.status)); return { status: bad ? 'degraded' : 'operational', message: [extractor?.detail, converter?.detail].filter(Boolean).join(' | ') || 'Microservice health endpoints reachable', detail: { extractor, converter, probe: 'health-workflow' } }; }
  if (key === 'n8n') return { status: health.status === 'ok' ? 'operational' : (health.status || 'unreachable'), message: `n8n health workflow returned ${health.status || 'unknown'}`, detail: { healthStatus: health.status, generatedAt: health.generatedAt, probe: 'health-workflow' } };
  if (key === 'jira') return { status: 'not_configured', message: 'Jira has no read-only live probe in this workflow yet; credential-backed project GET is the next step', detail: { probe: 'pending-credential-backed-node' } };
  if (key === 'confluence') return { status: 'not_configured', message: 'Confluence has no read-only live probe in this workflow yet; credential-backed space GET is the next step', detail: { probe: 'pending-credential-backed-node' } };
  if (key === 'openai') return { status: 'not_configured', message: 'OpenAI live validation is intentionally skipped to avoid cost; add a low-cost credential validation if required', detail: { probe: 'cost-guarded' } };
  return { status: 'not_configured', message: `${displayName || key} has no live probe configured`, detail: { probe: 'not-configured' } };
}
const p = probeFor(integrationKey, row?.display_name);
const integrationStatus = ['operational', 'degraded', 'unreachable', 'unauthorized', 'error', 'not_configured'].includes(p.status) ? p.status : 'error';
const result = { environment_key: envKey, integration_key: integrationKey, service_name: row?.display_name || integrationKey, status: integrationStatus, latency_ms: null, message: p.message, technical_detail: { ...p.detail, source: 'live-probe-api', checkedByName }, checked_by: checkedBy, checked_at: now };
const integrationPatch = { status: integrationStatus, last_tested_at: now, last_tested_by: checkedBy, updated_at: now };
return [{ json: { ok: true, environmentKey: envKey, integrationKey, status: integrationStatus, message: p.message, checkedAt: now, checkedBy, checkedByName, result, integrationPatch } }];
